# -*- coding: utf-8 -*-
import io, re

zh = io.open('docs/book/141-project-chat.md', encoding='utf-8').read()

def fences(src):
    out, lines, i = [], src.split('\n'), 0
    while i < len(lines):
        m = re.match(r'```(\S[^\n]*)?$', lines[i])
        if m:
            kind = m.group(1) or ''
            body, i = [], i + 1
            while i < len(lines) and not lines[i].startswith('```'):
                body.append(lines[i]); i += 1
            out.append((kind, '\n'.join(body)))
        i += 1
    return out

F = fences(zh)
assert len(F) == 16, len(F)

